//! Pure managed-schema to TypeScript declaration generation.

use crate::Result;
use serde_json::{Map, Value};
use std::collections::{BTreeMap, BTreeSet, HashSet};
use std::path::PathBuf;

const SHARED_TYPES: &str = r#"// GENERATED by `aic script workspace update` from the tenant's managed
// schema. Do not edit — re-run workspace update to refresh.
// RelationshipRef shape verified live against a managed record 2026-06-13.
interface RelationshipRef {
  _ref: string;
  _refResourceCollection?: string;
  _refResourceId?: string;
  _refProperties?: { _id?: string; _rev?: string } & Record<string, any>;
}
"#;

/// Workspace-relative path -> file contents for every generated managed type.
/// `schema` is the parsed body of `GET /openidm/config/managed`.
pub fn generate(schema: &Value) -> Result<Vec<(PathBuf, String)>> {
    let mut valid_objects = schema
        .get("objects")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|object| {
            let name = object.get("name").and_then(Value::as_str)?;
            let object_schema = object.get("schema")?;
            let properties = object_schema.get("properties")?.as_object()?;
            Some((name, object_schema, properties))
        })
        .collect::<Vec<_>>();
    valid_objects.sort_by(|a, b| a.0.cmp(b.0));

    let mut files = vec![(
        PathBuf::from("idm/types/managed/_shared.d.ts"),
        SHARED_TYPES.to_string(),
    )];
    for &(name, object_schema, properties) in &valid_objects {
        let interface_name = pascal_case(name);
        let contents = render_object(&interface_name, object_schema, properties)?;
        files.push((
            PathBuf::from("idm/types/managed").join(format!("{name}.d.ts")),
            contents,
        ));
        files.push((
            PathBuf::from("idm/types/managed/hooks").join(format!("{name}.d.ts")),
            render_hook_bindings(&interface_name),
        ));
    }
    files.push((
        PathBuf::from("idm/types/managed/openidm-map.d.ts"),
        render_managed_objects_map(&valid_objects),
    ));
    files.push((
        PathBuf::from("idm/types/managed/query-filter-fields.json"),
        render_query_filter_fields(&valid_objects)?,
    ));

    files.push((
        PathBuf::from("am/types/managed/_shared.d.ts"),
        SHARED_TYPES.to_string(),
    ));
    for &(name, object_schema, properties) in &valid_objects {
        let interface_name = pascal_case(name);
        files.push((
            PathBuf::from("am/types/managed").join(format!("{name}.d.ts")),
            render_object(&interface_name, object_schema, properties)?,
        ));
    }
    files.push((
        PathBuf::from("am/types/managed/openidm-map.d.ts"),
        render_managed_objects_map(&valid_objects),
    ));
    files.push((
        PathBuf::from("am/types/managed/query-filter-fields.json"),
        render_query_filter_fields(&valid_objects)?,
    ));

    Ok(files)
}

fn render_managed_objects_map(objects: &[(&str, &Value, &Map<String, Value>)]) -> String {
    let mut out = String::from(
        "// Collection path \u{2192} object interface. Merges into the empty\n// `interface ManagedObjects {}` declared by the engine's common types; the\n// conditional openidm signatures there key on it.\ninterface ManagedObjects {\n",
    );
    for &(name, _, _) in objects {
        let interface_name = pascal_case(name);
        out.push_str(&format!("  \"managed/{name}\": {interface_name};\n"));
    }
    out.push_str("}\n");
    out
}

fn render_query_filter_fields(objects: &[(&str, &Value, &Map<String, Value>)]) -> Result<String> {
    let mut map = BTreeMap::new();
    for &(name, _, properties) in objects {
        let mut fields = BTreeSet::from(["_id".to_string(), "_rev".to_string()]);
        for key in properties.keys() {
            fields.insert(key.clone());
        }
        map.insert(
            format!("managed/{name}"),
            fields.into_iter().collect::<Vec<_>>(),
        );
    }

    Ok(format!("{}\n", serde_json::to_string_pretty(&map)?))
}

fn render_hook_bindings(interface_name: &str) -> String {
    format!(
        "declare let object: {interface_name};\ndeclare const oldObject: {interface_name} | null;\ndeclare let newObject: {interface_name};\n"
    )
}

fn render_object(
    interface_name: &str,
    object_schema: &Value,
    properties: &Map<String, Value>,
) -> Result<String> {
    let required = object_schema
        .get("required")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .collect::<HashSet<_>>();
    let mut property_names = properties.keys().map(String::as_str).collect::<Vec<_>>();
    property_names.sort_unstable();

    let mut out = format!(
        "interface {interface_name} {{\n  // _id/_rev optional: present on stored/onUpdate records, absent on the onCreate draft.\n  _id?: string;\n  _rev?: string;\n"
    );
    for name in property_names {
        if matches!(name, "_id" | "_rev") {
            continue;
        }
        let key = property_key(name)?;
        let optional = if required.contains(name) { "" } else { "?" };
        let ty = property_type(&properties[name]);
        out.push_str(&format!("  {key}{optional}: {ty};\n"));
    }
    out.push_str("}\n");
    Ok(out)
}

fn property_key(name: &str) -> Result<String> {
    if is_typescript_identifier(name) {
        Ok(name.to_string())
    } else {
        Ok(serde_json::to_string(name)?)
    }
}

fn is_typescript_identifier(name: &str) -> bool {
    let mut bytes = name.bytes();
    let Some(first) = bytes.next() else {
        return false;
    };
    matches!(first, b'A'..=b'Z' | b'a'..=b'z' | b'_' | b'$')
        && bytes.all(|b| matches!(b, b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'_' | b'$'))
}

pub(crate) fn pascal_case(name: &str) -> String {
    let mut out = String::new();
    for segment in name
        .split(|c: char| !c.is_alphanumeric())
        .filter(|segment| !segment.is_empty())
    {
        let mut chars = segment.chars();
        if let Some(first) = chars.next() {
            out.extend(first.to_uppercase());
            out.extend(chars);
        }
    }
    if out.is_empty() || out.chars().next().is_some_and(char::is_numeric) {
        out.insert_str(0, "Obj");
    }
    out
}

fn property_type(property: &Value) -> String {
    match property.get("type") {
        Some(Value::String(kind)) => base_type(kind, property).to_string(),
        Some(Value::Array(kinds)) if kinds.iter().any(|kind| kind.as_str() == Some("null")) => {
            let base = kinds
                .iter()
                .filter_map(Value::as_str)
                .find(|kind| *kind != "null")
                .map(|kind| base_type(kind, property))
                .unwrap_or("any");
            format!("{base} | null")
        }
        _ => "any".to_string(),
    }
}

fn base_type<'a>(kind: &str, property: &'a Value) -> &'a str {
    match kind {
        "string" => "string",
        "boolean" => "boolean",
        "number" => "number",
        "object" => "Record<string, any>",
        "relationship" => "RelationshipRef",
        "array" => match property.pointer("/items/type").and_then(Value::as_str) {
            Some("string") => "string[]",
            Some("relationship") => "RelationshipRef[]",
            _ => "any[]",
        },
        _ => "any",
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn object_contents(schema: Value, name: &str) -> String {
        generate(&schema)
            .unwrap()
            .into_iter()
            .find(|(path, _)| path == &PathBuf::from(format!("idm/types/managed/{name}.d.ts")))
            .unwrap()
            .1
    }

    fn generated_contents(schema: &Value, path: &str) -> String {
        generate(schema)
            .unwrap()
            .into_iter()
            .find(|(candidate, _)| candidate == &PathBuf::from(path))
            .unwrap()
            .1
    }

    #[test]
    fn maps_scalars_nullable_and_required_properties() {
        let contents = object_contents(
            json!({
                "objects": [{
                    "name": "alpha_user",
                    "schema": {
                        "required": ["active", "profile"],
                        "properties": {
                            "displayName": {"type": "string"},
                            "active": {"type": "boolean"},
                            "score": {"type": "number"},
                            "profile": {"type": "object"},
                            "nickname": {"type": ["string", "null"]}
                        }
                    }
                }]
            }),
            "alpha_user",
        );

        assert!(contents.contains("active: boolean;"));
        assert!(contents.contains("displayName?: string;"));
        assert!(contents.contains("score?: number;"));
        assert!(contents.contains("profile: Record<string, any>;"));
        assert!(contents.contains("nickname?: string | null;"));
    }

    #[test]
    fn maps_arrays_and_relationships() {
        let contents = object_contents(
            json!({
                "objects": [{
                    "name": "alpha_user",
                    "schema": {"properties": {
                        "tags": {"type": "array", "items": {"type": "string"}},
                        "manager": {"type": "relationship"},
                        "reports": {"type": "array", "items": {"type": "relationship"}},
                        "mixed": {"type": "array", "items": {"type": "number"}}
                    }}
                }]
            }),
            "alpha_user",
        );

        assert!(contents.contains("tags?: string[];"));
        assert!(contents.contains("manager?: RelationshipRef;"));
        assert!(contents.contains("reports?: RelationshipRef[];"));
        assert!(contents.contains("mixed?: any[];"));
    }

    #[test]
    fn names_interfaces_and_quotes_non_identifier_keys() {
        let files = generate(&json!({
            "objects": [
                {"name": "mock_sms", "schema": {"properties": {}}},
                {"name": "alpha_user", "schema": {"properties": {
                    "weird-key": {"type": "string"}
                }}}
            ]
        }))
        .unwrap();

        let alpha = &files
            .iter()
            .find(|(path, _)| path.ends_with("alpha_user.d.ts"))
            .unwrap()
            .1;
        let sms = &files
            .iter()
            .find(|(path, _)| path.ends_with("mock_sms.d.ts"))
            .unwrap()
            .1;
        let am_alpha = &files
            .iter()
            .find(|(path, _)| path == &PathBuf::from("am/types/managed/alpha_user.d.ts"))
            .unwrap()
            .1;
        assert!(alpha.contains("interface AlphaUser"));
        assert!(alpha.contains("\"weird-key\"?: string;"));
        assert!(!alpha.contains("declare let object"));
        assert_eq!(alpha, am_alpha);
        assert!(sms.contains("interface MockSms"));
        assert_eq!(pascal_case("123-name"), "Obj123Name");
        assert_eq!(pascal_case("---"), "Obj");
    }

    #[test]
    fn golden_object_output_is_stable() {
        let contents = object_contents(
            json!({
                "objects": [{
                    "name": "alpha_user",
                    "schema": {
                        "required": ["active"],
                        "properties": {
                            "tags": {"type": "array", "items": {"type": "string"}},
                            "displayName": {"type": "string"},
                            "active": {"type": "boolean"}
                        }
                    }
                }]
            }),
            "alpha_user",
        );

        assert_eq!(
            contents,
            r#"interface AlphaUser {
  // _id/_rev optional: present on stored/onUpdate records, absent on the onCreate draft.
  _id?: string;
  _rev?: string;
  active: boolean;
  displayName?: string;
  tags?: string[];
}
"#
        );
    }

    #[test]
    fn hook_binding_output_is_stable_and_idm_only() {
        let schema = json!({
            "objects": [{
                "name": "alpha_user",
                "schema": {"properties": {}}
            }]
        });

        assert_eq!(
            generated_contents(&schema, "idm/types/managed/hooks/alpha_user.d.ts"),
            "declare let object: AlphaUser;\ndeclare const oldObject: AlphaUser | null;\ndeclare let newObject: AlphaUser;\n"
        );
        assert!(
            generate(&schema)
                .unwrap()
                .iter()
                .all(|(path, _)| !path.starts_with("am/types/managed/hooks"))
        );
    }

    #[test]
    fn emits_managed_objects_map_per_engine() {
        let schema = json!({
            "objects": [
                {"name": "zeta", "schema": {"properties": {}}},
                {"name": "alpha_user", "schema": {"properties": {}}}
            ]
        });
        let idm = generated_contents(&schema, "idm/types/managed/openidm-map.d.ts");
        let am = generated_contents(&schema, "am/types/managed/openidm-map.d.ts");

        assert!(idm.contains("interface ManagedObjects {"));
        assert!(idm.contains("\"managed/alpha_user\": AlphaUser;"));
        assert!(idm.contains("\"managed/zeta\": Zeta;"));
        assert!(
            idm.find("\"managed/alpha_user\"").unwrap() < idm.find("\"managed/zeta\"").unwrap()
        );
        assert_eq!(idm, am);
        assert!(idm.contains("Collection path → object interface."));
        assert!(idm.contains("conditional openidm signatures there key on it."));
    }

    #[test]
    fn emits_query_filter_field_map_per_engine() {
        let schema = json!({
            "objects": [
                {"name": "alpha_role", "schema": {"properties": {
                    "members": {"type": "array", "items": {"type": "relationship"}},
                    "name": {"type": "string"}
                }}},
                {"name": "alpha_user", "schema": {"properties": {
                    "userName": {"type": "string"}
                }}}
            ]
        });
        let idm = generated_contents(&schema, "idm/types/managed/query-filter-fields.json");
        let am = generated_contents(&schema, "am/types/managed/query-filter-fields.json");

        assert_eq!(idm, am);
        assert_eq!(
            idm,
            r#"{
  "managed/alpha_role": [
    "_id",
    "_rev",
    "members",
    "name"
  ],
  "managed/alpha_user": [
    "_id",
    "_rev",
    "userName"
  ]
}
"#
        );
    }

    #[test]
    fn shared_types_are_always_present_and_odd_objects_are_skipped() {
        let schema = json!({
            "objects": [
                {"name": "missing_schema"},
                {"schema": {"properties": {}}},
                {"name": "valid", "schema": {"properties": {}}}
            ]
        });
        let files = generate(&schema).unwrap();

        assert_eq!(files.len(), 9);
        assert_eq!(files[0].0, PathBuf::from("idm/types/managed/_shared.d.ts"));
        assert!(files[0].1.contains("interface RelationshipRef"));
        assert!(!files[0].1.contains("interface QueryResult<T>"));
        assert!(!files[0].1.contains("type ManagedField<T>"));
        assert!(
            files
                .iter()
                .any(|(path, _)| path == &PathBuf::from("idm/types/managed/openidm-map.d.ts"))
        );
        assert!(
            files
                .iter()
                .any(|(path, _)| path == &PathBuf::from("am/types/managed/openidm-map.d.ts"))
        );
        let am_shared = generated_contents(&schema, "am/types/managed/_shared.d.ts");
        assert!(!am_shared.contains("interface QueryResult<T>"));
        assert!(!am_shared.contains("type ManagedField<T>"));
        assert!(
            files
                .iter()
                .any(|(path, _)| path == &PathBuf::from("am/types/managed/valid.d.ts"))
        );

        let shared_only = generate(&json!({})).unwrap();
        assert_eq!(shared_only.len(), 6);
        assert!(shared_only[0].1.contains("interface RelationshipRef"));
        assert!(!shared_only[0].1.contains("type ManagedField<T>"));
        assert!(
            shared_only
                .iter()
                .any(|(path, _)| path == &PathBuf::from("idm/types/managed/openidm-map.d.ts"))
        );
        assert!(
            shared_only
                .iter()
                .any(|(path, _)| path == &PathBuf::from("am/types/managed/openidm-map.d.ts"))
        );
        assert_eq!(
            generated_contents(&json!({}), "idm/types/managed/openidm-map.d.ts"),
            "// Collection path \u{2192} object interface. Merges into the empty\n// `interface ManagedObjects {}` declared by the engine's common types; the\n// conditional openidm signatures there key on it.\ninterface ManagedObjects {\n}\n"
        );
        assert_eq!(
            generated_contents(&json!({}), "idm/types/managed/query-filter-fields.json"),
            "{}\n"
        );
    }
}
